INSERT INTO product_reviews VALUES(4,'ae109cdb','{"ua":"Ірина Сергіївна","en":"Iryna Serhiivna"}',5,'{"ua":"Дуже ніжна модель, ідеально виглядає на тонкій руці. Якість на висоті.","en":"Very delicate model, looks perfect on a slim hand. Top quality."}',17,'2026-03-07',1,'{"ua":"Ірино, дякуємо за відгук! Рада, що каблучка вам пасує. Гарного дня!","en":"Iryna, thank you for the review! Glad the ring suits you. Have a great day!"}',4,'2026-03-07');
INSERT INTO product_reviews VALUES(5,'c3ffa7e4','{"ua":"Софія Миколаївна","en":"Sofiia Mykolaivna"}',5,'{"ua":"Це кохання з першого погляду. Камені сяють, золото м’яке, розмір точний.","en":"Love at first sight. Stones shine, gold is soft, size is exact."}',34,'2026-03-08',1,'{"ua":"Софія, дуже приємно чути! Бажаємо, щоб каблучка радувала вас щодня.","en":"Sofiia, so nice to hear! Wishing the ring brings you joy every day."}',8,'2026-03-08');
