INSERT INTO product_reviews VALUES(7,'543ea15h','{"ua":"Олександр Володимирович","en":"Oleksandr Volodymyrovych"}',5,'{"ua":"Дуже сподобалась каблучка, подарував дружині на річницю — сльози щастя. Якість на висоті!","en":"Really liked the ring, gave it to my wife for our anniversary — tears of happiness. Top-notch quality!"}',32,'2026-03-17',1,'{"ua":"Олександре, дуже приємно чути такі слова! ❤️ Бажаємо вам і вашій дружині ще багато щасливих моментів разом.","en":"Oleksandr, so nice to hear such words! ❤️ Wishing you and your wife many more happy moments together."}',11,'2026-03-17');
INSERT INTO product_reviews VALUES(8,'7760bc2','{"ua":"Катерина Романівна","en":"Kateryna Romanivna"}',5,'{"ua":"Ідеальна каблучка на кожен день. Не відчувається на руці, виглядає стильно.","en":"Perfect everyday ring. Doesn’t feel on the hand, looks stylish."}',15,'2026-03-10',1,'{"ua":"Катерино, дякуємо! Рада, що каблучка стала комфортною частиною вашого образу.","en":"Kateryna, thank you! Glad the ring became a comfortable part of your look."}',3,'2026-03-10');
