INSERT INTO product_reviews VALUES(14,'97ee529','{"ua":"Ольга Сергіївна","en":"Olha Serhiivna"}',5,'{"ua":"Чудова обручка! Дуже ніжна, двоколірне золото виглядає дорого і стильно. Розмір підійшов ідеально.","en":"Wonderful wedding ring! Very delicate, two-tone gold looks expensive and stylish. The size fit perfectly."}',24,'2026-03-19',1,'{"ua":"Ольго, дякуємо за відгук! Рада, що обручка сподобалась. Бажаємо щасливого сімейного життя!","en":"Olha, thank you for the review! Glad you liked the ring. Wishing you a happy family life!"}',7,'2026-03-19');
INSERT INTO product_reviews VALUES(15,'bfaa7c0e','{"ua":"Катерина Павлівна","en":"Kateryna Pavlivna"}',5,'{"ua":"Дуже гарна каблучка! Гранат у формі серця виглядає надзвичайно романтично. Якість відмінна.","en":"Very beautiful ring! The heart-shaped garnet looks incredibly romantic. Excellent quality."}',18,'2026-03-20',0,NULL,0,NULL);
INSERT INTO product_reviews VALUES(16,'2c4312fs','{"ua":"Наталія Андріївна","en":"Nataliia Andriivna"}',2,'{"ua":"Каблучка сама гарна і якісна, але прислали не той розмір. Доведеться здавати назад.","en":"The ring itself is beautiful and high quality, but they sent the wrong size. I have to return it."}',5,'2026-03-21',1,'{"ua":"Наталіє, вибачте за незручність з розміром! Будь ласка, надішліть фото каблучки — ми оперативно організуємо обмін.","en":"Nataliia, sorry for the size inconvenience! Please send a photo of the ring — we will quickly arrange an exchange."}',9,'2026-03-21');
INSERT INTO product_reviews VALUES(17,'06088e7','{"ua":"Ірина Дмитрівна","en":"Iryna Dmytrivna"}',5,'{"ua":"Супер стильна каблучка! Легка, сучасна, етно-мотиви виглядають дуже круто. Рекомендую!","en":"Super stylish ring! Lightweight, modern, the ethnic motifs look really cool. Highly recommend!"}',15,'2026-03-22',0,NULL,0,NULL);
INSERT INTO product_reviews VALUES(18,'b6b083fe','{"ua":"Анна Миколаївна","en":"Anna Mykolaivna"}',2,'{"ua":"Само кільце підійшло ідеально по розміру, але прийшло з відламаним каменем. Дуже засмутилась.","en":"The ring itself fit perfectly in size, but it arrived with a broken stone. I was very upset."}',11,'2026-03-23',1,'{"ua":"Анно, дуже шкода, що так сталося! Будь ласка, надішліть фото — ми негайно вирішимо питання з заміною.","en":"Anna, we are very sorry this happened! Please send a photo — we will immediately resolve the replacement."}',12,'2026-03-23');
INSERT INTO product_reviews VALUES(19,'d41a711f','{"ua":"Анна Сергіївна","en":"Anna Serhiivna"}',5,'{"ua":"Каблучка просто чудова! Два сердечка з червоним цирконом виглядають дуже романтично і ніжно. Якість відмінна, камінці блищать гарно. Розмір підійшов ідеально.","en":"The ring is just wonderful! The two hearts with red zirconia look very romantic and delicate. Excellent quality, the stones sparkle beautifully. The size fit perfectly."}',27,'2026-03-25',1,'{"ua":"Анно, дякуємо за такий теплий відгук! ❤️ Раді, що каблучка сподобалась. Бажаємо носити з радістю!","en":"Anna, thank you for such a warm review! ❤️ Glad you liked the ring. Wishing you to wear it with joy!"}',8,'2026-03-25');
INSERT INTO product_reviews VALUES(20,'d41a711f','{"ua":"Світлана Миколаївна","en":"Svitlana Mykolaivna"}',5,'{"ua":"Дуже красиве кільце! Сердечка виглядають мило і елегантно одночасно. Циркон яскравий, не облазить. Носжу щодня і отримую компліменти.","en":"Very beautiful ring! The hearts look cute and elegant at the same time. The zirconia is bright and doesn’t fade. I wear it every day and get compliments."}',19,'2026-03-26',1,'{"ua":"Світлано, дякуємо! Дуже приємно чути, що каблучка приносить вам радість. Якщо будуть питання — пишіть будь-коли.","en":"Svitlana, thank you! So nice to hear that the ring brings you joy. If you have any questions — feel free to write anytime."}',5,'2026-03-26');
INSERT INTO product_reviews VALUES(21,'dfd0e847a','{"ua":"Вікторія Олегівна","en":"Viktoriia Olehivna"}',3,'{"ua":"Каблучка в цілому нормальна, розмір підійшов, вигляд стильний. Але центральна вставка (чорний квадрат) приїхала з помітними подряпинами. Трохи засмутило.","en":"The ring is generally okay, the size fit, stylish look. But the central insert (black square) arrived with noticeable scratches. It was a bit disappointing."}',12,'2026-03-27',1,'{"ua":"Вікторіє, дякуємо за відгук і вибачте за незручність з вставкою. Будь ласка, надішліть фото — ми оперативно вирішимо питання з заміною.","en":"Viktoriia, thank you for the review and sorry for the inconvenience with the insert. Please send a photo — we will quickly resolve the replacement."}',6,'2026-03-27');
INSERT INTO product_reviews VALUES(22,'dfd0e847a','{"ua":"Дмитро Олександрович","en":"Dmytro Oleksandrovych"}',4,'{"ua":"Кільце гарне, виглядає солідно і стильно. Камінь тримається добре, розмір підійшов. Єдине — ціна, на мою думку, трохи завищена за таке якість.","en":"The ring is nice, looks solid and stylish. The stone holds well, the size fit. The only thing is that the price, in my opinion, is a bit overpriced for this quality."}',14,'2026-03-28',1,'{"ua":"Дмитре, дякуємо за відгук! Раді, що каблучка вам сподобалась. Ціну формуємо з урахуванням якості матеріалів та роботи. Якщо будуть питання — завжди на зв’язку.","en":"Dmytro, thank you for the review! Glad you liked the ring. We form the price taking into account the quality of materials and workmanship. If you have any questions — we are always in touch."}',5,'2026-03-28');
INSERT INTO product_reviews VALUES(23,'2dac5872','{"ua":"Марія Андріївна","en":"Mariia Andriivna"}',5,'{"ua":"Дуже красиві сережки! Сердечки з насиченим синім каменем виглядають яскраво і святково. Якість хороша, застібка зручна.","en":"Very beautiful earrings! The hearts with rich blue stones look bright and festive. Good quality, comfortable clasp."}',22,'2026-03-28',1,'{"ua":"Маріє, дякуємо за відгук! Раді, що сережки вам сподобались. Бажаємо носити з задоволенням!","en":"Mariia, thank you for the review! Glad you liked the earrings. Wishing you to wear them with pleasure!"}',6,'2026-03-28');
