INSERT INTO product_reviews VALUES(26,'61d15f28','{"ua":"Тетяна Володимирівна","en":"Tetiana Volodymyrivna"}',5,'{"ua":"Чудові сережки! Синій колір дуже насичений і яскравий. Сердечки милі та романтичні. Якість на висоті.","en":"Wonderful earrings! The blue color is very rich and bright. The hearts are cute and romantic. Top quality."}',17,'2026-03-31',1,'{"ua":"Тетяно, дякуємо! Раді, що сережки сподобались. Бажаємо, щоб вони радували вас щодня.","en":"Tetiana, thank you! Glad you liked the earrings. Wishing they bring you joy every day."}',5,'2026-03-31');
