INSERT INTO product_reviews VALUES(33,'uz33678620','{"ua":"Наталія Дмитрівна","en":"Nataliia Dmytrivna"}',4,'{"ua":"Хороший ювелірний ланцюжок. Якісне плетіння, зручний. Трохи важкуватий, але виглядає солідно.","en":"Good jewelry chain. Quality weaving, comfortable. A bit heavy, but looks solid."}',15,'2026-04-07',1,'{"ua":"Наталіє, дякуємо за відгук! Раді, що ланцюжок вам сподобався.","en":"Nataliia, thank you for the review! Glad you liked the chain."}',5,'2026-04-07');
INSERT INTO products VALUES('a4725354','rings','["https://img.ukrzoloto.ua/images/pr/520_520/a8139709f7cb446e625896260dce3294/1717602331/UZ32166905_000158841.webp", "https://img.ukrzoloto.ua/images/pr/520_520/1c94856c4c8b1ef336d354af780fea76/1717602331/UZ32166905_000158841-m_1.webp", "https://img.ukrzoloto.ua/images/pr/520_520/42dd5860199eab1facd36f4b58e9c73a/1717602331/UZ32166905_000158841-r_1.webp"]','{"ua":"Каблучка для заручин з білого золота з еко-діамантами","en":"White gold engagement ring with eco-diamonds"}',1000,0,NULL,5,2,1.75,'{"ua":"Класичний, Мінімалізм", "en":"Classic, Minimalism"}','{"ua":"Весільна","en":"Wedding"}','{"ua":"Золото","en":"Gold"}','{"ua":"Білий","en":"White"}',585,'{"ua":"Жінкам","en":"Woman"}','1','{"ua":"Еко-Діамант","en":"Eco-diamond"}','{"ua":"Ця просто чудова обручка вирізняється елегантним дизайном з білого золота 14 карат у стилі весільної класики з мінімалістичними формами. Лаконічний силует підкреслює витонченість прикраси, а делікатні деталі створюють гармонійний баланс між простотою та вишуканістю. Каблучка ідеально підходить для щоденного носіння та символізує чистоту почуттів і вічність союзу.", "en":"This simply gorgeous wedding ring stands out with an elegant design in 14K white gold in a classic bridal style with minimalist forms. The clean silhouette highlights the sophistication of the piece, while delicate details create a harmonious balance between simplicity and refinement. The ring is perfect for everyday wear and symbolizes purity of feelings and the eternity of a union."}',0,1,'{"ua":"Дівчині, Дружині","en":"Girlfriend, Wife"}','{"size":17}');
INSERT INTO products VALUES('40fb4f28','rings','["https://img.ukrzoloto.ua/images/pr/520_520/0a6e16484411bfb899a0d867bf7dd6ab/1747748306/UZ35982616_000172364.webp", "https://img.ukrzoloto.ua/images/pr/520_520/f5cfb99ab34f008c29d372b329c16300/1747748306/UZ35982616_000172364-m_1.webp", "https://img.ukrzoloto.ua/images/pr/520_520/d71b026bc40da16fe94da3877d8ea691/1752736602/UZ35982616_000172364-t_1.webp", "https://img.ukrzoloto.ua/images/pr/520_520/5f093e8c40af802dadb36a2962aa7780/1752736602/UZ35982616_000172364-f_1.webp"]','{"ua":"Каблучка з білого золота з лабораторними діамантами 53695-3.0-L/02/1/11901","en":"White gold ring with eco-diamonds 53695-3.0-L/02/1/11901"}',1294,0,NULL,5,1,1.5,'{"ua":"Класичний", "en":"Classic"}','{"ua":"Весільна", "en":"Wedding"}','{"ua":"Золото","en":"Gold"}','{"ua":"Білий","en":"White"}',585,'{"ua":"Жінкам","en":"Woman"}','5','{"ua":"Еко-Діамант","en":"Eco-diamond"}','{"ua":"Ця розкішна весільна каблучка прикрашена п’ятьма діамантами, які розташовані в одну витончену лінію та створюють ефект безперервного сяйва. Основа виконана з благородного металу та має класичний дизайн, що підкреслює стриману елегантність і вишуканий смак. Гармонійне поєднання пропорцій і блиску каменів робить прикрасу ідеальним символом кохання та вірності. Каблучка чудово пасує як для щоденного носіння, так і для особливих моментів.","en":"This luxurious wedding ring is adorned with five diamonds arranged in a refined line, creating a continuous sparkle effect. The band is crafted from noble metal with a classic design that emphasizes understated elegance and refined taste. The harmonious combination of proportions and the brilliance of the stones makes the piece a perfect symbol of love and devotion. The ring is well suited for everyday wear as well as special occasions."}',0,1,'{"ua":"Дівчині, Дружині, Доньці, Подрузі","en":"Girlfriend, Wife, Daughter"}','{"size":17}');
INSERT INTO products VALUES('ae109cdb','rings','["https://img.ukrzoloto.ua/images/pr/520_520/68501186540df9e8997205a51e920c60/1770223392/UZ30640040_000160130.webp", "https://img.ukrzoloto.ua/images/pr/520_520/56be18a131cdde76191256ea92ae63b3/1726830816/UZ30640040_000160130-m_1.webp", "https://img.ukrzoloto.ua/images/pr/520_520/6b8e3aa87987dc8d182d7331984f2339/1726830816/UZ30640040_000160130-r_1.webp", "https://img.ukrzoloto.ua/images/pr/520_520/3768c314ab0490da8f109e4c3472e420/1729256041/UZ30640040_000160130-f_1.webp", "https://img.ukrzoloto.ua/images/pr/520_520/9ea633f504e0fb8946ee5a4590f7a412/1729256041/UZ30640040_000160130-f_3.webp"]','{"ua":"Каблучка двоколірного золота з діамантами 53689/14/1/11360","en":"Two-tone gold ring with diamonds 53689/14/1/11360"}',1280,1,2000,5,1,2,'{"ua":"Модерн", "en":"Modern"}','{"ua":"Повсякденна", "en":"Everyday"}','{"ua":"Золото","en":"Gold"}','{"ua":"Комбінований","en":"Two-tone"}',585,'{"ua":"Унісекс","en":"Unisex"}','10+','{"ua":"Діамант","en":"Diamond"}','{"ua":"Ця вишукана каблучка з двокольорового золота поєднує в собі елегантність класичного дизайну та сучасну гармонію форм. Контраст теплого червоного та світлого відтінків металу створює виразний візуальний акцент, підкреслюючи витонченість кожної деталі. Полірована поверхня додає виробу благородного блиску, а продуманий мінімалістичний стиль робить каблучку універсальною для щоденного носіння. Прикраса виглядає стримано, але водночас дорого та статусно, підкреслюючи індивідуальність власниці.","en":"This elegant two-tone gold ring combines the sophistication of a classic design with modern harmony of forms. The contrast between warm red and light metal tones creates a striking visual accent that highlights the refinement of every detail. The polished surface adds a noble shine, while the thoughtful minimalist style makes the ring versatile for everyday wear. The piece looks understated yet luxurious and статусно, emphasizing the individuality of its wearer."}',0,1,'{"ua":"Дівчині, Дружині, Мамі, Подрузі", "en":"Girlfriend, Wife, Mother, Friend"}','{"size":18}');
INSERT INTO products VALUES('c3ffa7e4','rings','["https://img.ukrzoloto.ua/images/pr/520_520/95cca969a11070c7ec8da6eeedcaf745/1725539810/UZ31344799_000159732.webp", "https://img.ukrzoloto.ua/images/pr/520_520/7dbfd9461e813e49b4c5f7e10392166c/1725539809/UZ31344799_000159732-m_1.webp", "https://img.ukrzoloto.ua/images/pr/520_520/bfbf37e89646503acdbe82f08cf83d85/1725539810/UZ31344799_000159732-r_1.webp", "https://img.ukrzoloto.ua/images/pr/520_520/ad95cc79f0ad3b3c872ed6155826b745/1728494465/UZ31344799_000159732-t_1.webp", "https://img.ukrzoloto.ua/images/pr/520_520/21bf9db08fa192a59672556f42dde3c9/1728588388/UZ31344799_000159732-f_1.webp", "https://img.ukrzoloto.ua/images/pr/520_520/b3f0c6181c0ae6f1e03b550f2944d36f/1728588388/UZ31344799_000159732-f_3.webp"]','{"ua":"Каблучка з червоного золота з кубічним цирконієм 1190143101-R/01/1","en":"Red gold ring with cubic zirconia 1190143101-R/01/1"}',235,0,NULL,5,1,1.5,'{"ua":"Модерн, Доріжка", "en":"Modern, Path"}','{"ua":"Повсякденна","en":"Everyday"}','{"ua":"Золото","en":"Gold"}','{"ua":"Червоний","en":"Red"}',585,'{"ua":"Жінкам","en":"Woman"}','10+','{"ua":"Фіаніт","en":"Cubic zirconia"}','{"ua":"Елегантна каблучка з червоного золота виконана у сучасному стилі «доріжка», де ряд сяючих каменів створює ефект безперервного блиску. Витончена форма виробу поєднує в собі легкість модерну та класичну стриманість, завдяки чому прикраса виглядає гармонійно та універсально. Тонка основа підкреслює сяйво вставок і додає каблучці вишуканого характеру. Це повсякденна прикраса, яка ідеально доповнює як діловий, так і повсякденний образ.","en":"An elegant red gold ring crafted in a modern “path” style, where a line of sparkling stones creates a continuous brilliance effect. The refined shape combines modern lightness with classic restraint, making the piece look harmonious and versatile. The delicate band enhances the brilliance of the stones and adds a sophisticated character to the ring. This is an everyday piece that perfectly complements both business and casual looks."}',0,1,'{"ua":"Дівчині, Дружині, Мамі, Подрузі", "en":"Girlfriend, Wife, Mother, Friend"}','{"size":16}');
INSERT INTO products VALUES('543ea15h','rings','["https://img.ukrzoloto.ua/images/pr/520_520/49f7e70c4faa0c705b53ba291d6a7328/1711699825/UZ13616_000061642.webp", "https://img.ukrzoloto.ua/images/pr/520_520/a68062ed403fb9d1d7711ceb0bca948c/1711699824/UZ13616_000061642-m_1.webp", "https://img.ukrzoloto.ua/images/pr/520_520/09d4e0de7f315a85dc076cfe37eed6fa/1718703434/UZ13616_000061642-t_1.webp", "https://img.ukrzoloto.ua/images/pr/520_520/34b0ad391712ffeaf0a716a11d3083ae/1718963588/UZ13616_000061642-f_1.webp", "https://img.ukrzoloto.ua/images/pr/520_520/9bc31b9608dfbf5b3a184d61a8d88228/1718963589/UZ13616_000061642-f_3.webp"]','{"ua":"Каблучка з червоного золота з фіанітами 12052","en":"Red gold ring with cubic zirconia 12052"}',3600,1,4000,4.5,2,2.20000000000000017,'{"ua":"Модерн, Органіка", "en":"Modern, Organic"}','{"ua":"Серце","en":"Heart"}','{"ua":"Золото","en":"Gold"}','{"ua":"Червоний","en":"Red"}',585,'{"ua":"Жінкам","en":"Woman"}','10+','{"ua":"Фіаніт","en":"Cubic zirconia"}','{"ua":"Елегантна каблучка з червоного золота, прикрашена сяючим центральним фіанітом у витонченому обрамленні з дрібних каменів. Вишуканий дизайн із декоративними елементами у формі сердець надає прикрасі особливого шарму.","en":"An elegant red gold ring adorned with a sparkling central cubic zirconia surrounded by smaller shimmering stones. The sophisticated design with heart-shaped decorative elements adds a touch of refined charm to the piece."}',0,1,'{"ua":"Дівчині, Дружині, Мамі, Подрузі", "en":"Girlfriend, Wife, Mother, Friend"}','{"size":17}');
INSERT INTO products VALUES('d41a711f','rings','["https://img.ukrzoloto.ua/images/pr/520_520/dafc7a2443f18ad533903c93cbc8ce97/1744716254/UZ13638_000006110_.webp", "https://img.ukrzoloto.ua/images/pr/520_520/c5ea5b0f637be72da7ce43bf7bfca2d0/1741770604/UZ13638_000006110-m_1.webp", "https://img.ukrzoloto.ua/images/pr/520_520/3e04f9d4f55095f2c75f5f881e9dcd2b/1741770605/UZ13638_000006110-t_1.webp", "https://img.ukrzoloto.ua/images/pr/520_520/ba9d6d155f0a7b349ada8f17956a3651/1703626503/UZ13638_000006110-f_1.jpg", "https://img.ukrzoloto.ua/images/pr/520_520/234c3ccacba7feb3055800ee6e27ee8a/1703626504/UZ13638_000006110-f_2.webp"]','{"ua":"Каблучка з червоного золота у формі серця 12355","en":"Red gold heart-shaped ring 12355"}',350,0,NULL,5,2,1.35000000000000008,'{"ua":"Милий, Мінімалізм, Романтичний", "en":"Cute, Minimalism, Romantic"}','{"ua":"Повсякденна, Серце", "en":"Everyday, Heart"}','{"ua":"Золото","en":"Gold"}','{"ua":"Червоний","en":"Red"}',585,'{"ua":"Жінкам","en":"Woman"}','2','{"ua":"Без вставки","en":"Not"}','{"ua":"Кільце з червоного золота, виконане в техніці філігранного плетіння, є вишуканим ювелірним виробом, що поєднує тонкість ручної роботи та витончену естетику. Делікатні ажурні візерунки створюють легку та повітряну структуру, підкреслюючи майстерність виконання та унікальність дизайну. У центрі композиції гармонійно розміщений декоративний елемент у формі серця, що додає прикрасі романтичного змісту та м’якості образу. Це аксесуар, який підкреслює красу почуттів і стане особливим подарунком для коханої людини.","en":"A red gold ring crafted in filigree technique is an exquisite piece of jewelry that combines the delicacy of handcrafted work with refined aesthetics. The delicate openwork patterns create a light and airy structure, emphasizing the craftsmanship and uniqueness of the design. A decorative heart-shaped element is harmoniously placed in the composition, adding a romantic meaning and softness to the piece. This accessory highlights the beauty of feelings and makes a special gift for a loved one."}',0,0,'{"ua":"Дівчині, Дружині, Мамі, Подрузі", "en":"Girlfriend, Wife, Mother, Friend"}','{"size":16}');
INSERT INTO products VALUES('764ea9fb','rings','["https://img.ukrzoloto.ua/images/pr/520_520/4dde17b452df576f2940853701ed6ace/1686054683/UZ60954_000123216.webp", "https://img.ukrzoloto.ua/images/pr/520_520/f3a2b9c16231c7bee67084cddbb1b629/1686054682/UZ60954_000123216-m_1.webp", "https://img.ukrzoloto.ua/images/pr/520_520/146ba2d752b22dad946de4dff7935f8c/1686054683/UZ60954_000123216-r_1.webp", "https://img.ukrzoloto.ua/images/pr/520_520/54128048c5598db28f16696fbb327637/1686054682/UZ60954_000123216-f_1.webp"]','{"ua":"Каблучка з золота з кубічним цирконієм Tender leaf","en":"Gold ring with cubic zirconia Tender leaf"}',6619,1,9600,2,1,0.869999999999999995,'{"ua":"Модерн, Органіка, Доріжка", "en":"Modern, Organic, Path"}','{"ua":"Повсякденна", "en":"Everyday"}','{"ua":"Золото","en":"Gold"}','{"ua":"Червоний","en":"Red"}',585,'{"ua":"Жінкам","en":"Woman"}','0','{"ua":"Фіаніт","en":"Cubic zirconia"}','{"ua":"Легка, елегантна ювелірна прикраса в стилі органік і модерн, що вирізняється плавними природними лініями та гармонійною формою. Дизайн натхненний природними мотивами, завдяки чому виріб виглядає м’яко та витончено, без зайвої декоративності. Полірована поверхня підкреслює благородний блиск металу та додає прикрасі сучасного звучання. Це повсякденна прикраса, яка легко поєднується з різними стилями одягу та підкреслює індивідуальність у щоденному образі.","en":"A light, elegant piece of jewelry in an organic and modern style, characterized by smooth natural lines and a harmonious shape. The design is inspired by natural motifs, giving the piece a soft and refined look without excessive decoration. The polished surface enhances the noble shine of the metal and adds a contemporary touch. This is an everyday piece that easily complements different outfits and emphasizes individuality in daily wear."}',0,1,'{"ua":"Дружині, Дівчині","en":"Wife, Girlfriend"}','{"size":15}');
INSERT INTO products VALUES('7202a5d9','rings','["https://img.ukrzoloto.ua/images/pr/520_520/2a197f0cccba24a7ba5a2743532d9e6c/1689960507/UZ26624730_000154912.webp", "https://img.ukrzoloto.ua/images/pr/520_520/3b33f8b2ab70593d09857af81d538feb/1689960507/UZ26624730_000154912-m_1.webp", "https://img.ukrzoloto.ua/images/pr/520_520/1dffb6f1c9aef8d1d800d199300872ed/1690454907/UZ26624730_000154912-r_1.webp", "https://img.ukrzoloto.ua/images/pr/520_520/9fa872cc9d151b8de65c7823b4c4c962/1689962855/UZ26624730_000154912-t_1.webp", "https://img.ukrzoloto.ua/images/pr/520_520/d7822f440a169b1d3efbe887ead2688f/1689962855/UZ26624730_000154912-f_1.webp", "https://img.ukrzoloto.ua/images/pr/520_520/b1bad30924976ca01df120dfa9db53d6/1689962855/UZ26624730_000154912-f_2.webp"]','{"ua":"Каблучка заручинна Tesori Zirconia з червоного золота з кубічним цирконієм 12426/01/0/4183","en":"Tesori Zirconia Red Gold Engagement Ring with Cubic Zirconia 12426/01/0/4183"}',343.839999999999975,0,NULL,4,2,1.46999999999999997,'{"ua":"Класичний, Елегантний", "en":"Classic, Elegant"}','{"ua":"Заручини, Повсякденна", "en":"Engagement, Everyday"}','{"ua":"Золото","en":"Gold"}','{"ua":"Червоний","en":"Red"}',585,'{"ua":"Жінкам","en":"Woman"}','7','{"ua":"Tesori цирконій, Фіаніт","en":"Tesori Zirconia, Cubic zirconia"}','{"ua":"Ця захоплива обручка з колекції Tesori Zirconia вирізняється витонченим дизайном і сяючими вставками, що створюють ефект розкішного блиску. Гармонійне поєднання благородного металу та декоративних елементів підкреслює елегантність і сучасний характер прикраси. Продумана форма каблучки забезпечує комфорт під час носіння, а делікатне сяйво каменів додає виробу особливої виразності. Це прикраса, яка ідеально підходить для заручин та підкреслює значущість особливих моментів.","en":"This breathtaking engagement ring from the Tesori Zirconia collection features a refined design and sparkling accents that create a luxurious brilliance effect. The harmonious combination of noble metal and decorative elements highlights the elegance and modern character of the piece. The well-balanced shape ensures comfortable wear, while the delicate shimmer of the stones adds special expressiveness. This ring is perfect for engagement and emphasizes the significance of life’s most important moments."}',0,1,'{"ua":"Дівчині, Дружині, Мамі, Подрузі", "en":"Girlfriend, Wife, Mother, Friend, Husband, Dad"}','{"size":15}');
INSERT INTO products VALUES('f680b5380','rings','["https://img.ukrzoloto.ua/images/pr/520_520/01b554fd6e361d8c684be13b06cbde69/1718351207/UZ13253_000103666.webp", "https://img.ukrzoloto.ua/images/pr/520_520/e115fd97ab5b741237142f6328ce44fd/1718351207/UZ13253_000103666-m_1.webp", "https://img.ukrzoloto.ua/images/pr/520_520/c14cb258671cace747e7527d590a305a/1725097548/UZ13253_000103666-t_1.webp", "https://img.ukrzoloto.ua/images/pr/520_520/b77303f3b4400188c7329cfafb0aab07/1724247822/UZ13253_000103666-f_1.webp", "https://img.ukrzoloto.ua/images/pr/520_520/7df681ef584bccd0447d6111b170e63d/1724247822/UZ13253_000103666-f_3.webp"]','{"ua":"Класична обручка з червоного золота UZ872","en":"Classic Red Gold Wedding Band UZ872"}',133,1,210,5,1,1.31000000000000005,'{"ua":"Класичний", "en":"Classic"}','{"ua":"Весільна","en":"Wedding"}','{"ua":"Золото","en":"Gold"}','{"ua":"Червоний","en":"Red"}',375,'{"ua":"Унісекс", "en":"Unisex"}','0','{"ua":"Без вставки","en":"Not"}','{"ua":"Вічна класика, виготовлена з теплого червоного золота, що символізує стабільність і чистоту почуттів. Лаконічний дизайн без зайвих декоративних елементів підкреслює стриману елегантність і бездоганний смак. Гладка полірована поверхня додає каблучці благородного блиску та робить її універсальною для щоденного носіння. Це весільна прикраса, створена як символ вірності та міцного союзу, що залишається актуальною поза часом.","en":"A timeless classic crafted from warm red gold, symbolizing stability and purity of feelings. The minimalist design without unnecessary decorative elements emphasizes understated elegance and impeccable taste. The smooth polished surface adds a noble shine and makes the ring versatile for everyday wear. This wedding piece is created as a symbol of fidelity and a strong union, remaining relevant beyond time."}',0,1,'{"ua":"Дівчині, Нареченій, Дружині","en":"Girlfriend, Bride, Wife, Husband, Dad, Boyfriend"}','{"size":17}');
INSERT INTO products VALUES('86ead98d','rings','["https://img.ukrzoloto.ua/images/pr/520_520/ee124582ae40defa56b7ab08c5e0a055/1717772707/UZ37436_000122285.webp", "https://img.ukrzoloto.ua/images/pr/520_520/1853227501fd81223151659ec76c0a0e/1703626342/UZ37436_000122285-f_1.webp", "https://img.ukrzoloto.ua/images/pr/520_520/7ee1847a78e321ed4f22bc780c09f40c/1703626343/UZ37436_000122285-f_2.webp"]','{"ua":"Каблучка з комбінованого золота з фіанітами UZ37436","en":"Two-tone gold ring with cubic zirconia UZ37436"}',6890,1,10450,0,0,0.920000000000000039,'{"ua":"Елегантний, Доріжка","en":"Elegant, Path"}','{"ua":"Повсякденна","en":"Everyday"}','{"ua":"Золото","en":"Gold"}','{"ua":"Комбінований","en":"Two-tone"}',585,'{"ua":"Жінкам","en":"Woman"}','10+','{"ua":"Фіаніт","en":"Cubic zirconia"}','{"ua":"Втілення вишуканості у повсякденній прикрасі, виконаній у елегантному стилі «доріжка», де ряд сяючих каменів створює ефект безперервного блиску. Тонка й витончена форма каблучки підкреслює легкість дизайну та додає образу делікатного шарму. Гармонійне поєднання благородного металу та сяйва вставок робить прикрасу універсальною для щоденного носіння. Це стильний аксесуар, який м’яко доповнює будь-який образ і підкреслює витонченість смаку.","en":"An embodiment of elegance in an everyday piece crafted in a refined “path” style, where a line of sparkling stones creates a continuous brilliance effect. The slim and delicate shape of the ring emphasizes the lightness of the design and adds a subtle charm to the look. The harmonious combination of noble metal and shimmering stones makes the piece versatile for daily wear. This stylish accessory gently complements any outfit and highlights refined taste."}',0,1,'{"ua":"Дівчині, Дружині, Мамі","en":"Girlfriend, Wife, Mom"}','{"size":16}');
INSERT INTO products VALUES('7760bc2','rings','["https://img.ukrzoloto.ua/images/pr/520_520/7ec37c0d754f78d150e4cf1851446c76/1765545151/UZ10031134_000135352.webp", "https://img.ukrzoloto.ua/images/pr/520_520/90376cd9aa95545db30f434d34feebee/1765545150/UZ10031134_000135352-m_1.webp", "https://img.ukrzoloto.ua/images/pr/520_520/c9b1fc5af3981ff9c927cec970d5fcee/1691410614/UZ10031134_000135352-f_1.webp", "https://img.ukrzoloto.ua/images/pr/520_520/9bf8dd89b17098253ef2900d2efa3b74/1691410614/UZ10031134_000135352-f_3.webp"]','{"ua":"Каблучка з комбінованого золота з фіанітами UZ10031134","en":"Two-tone gold ring with cubic zirconia UZ10031134"}',11300,1,17200,5,1,1.51,'{"ua":"Елегантний, Доріжка","en":"Elegant, Path"}','{"ua":"Заручини, Повсякденна","en":"Engagement, Everyday"}','{"ua":"Золото","en":"Gold"}','{"ua":"Комбінований","en":"Two-tone"}',585,'{"ua":"Жінкам","en":"Woman"}','7','{"ua":"Фіаніт","en":"Cubic zirconia"}','{"ua":"Витончена каблучка з червоного золота 585 проби виконана у повсякденному стилі «доріжка», де ряд сяючих каменів створює ефект безперервного блиску. Лаконічна форма виробу підкреслює елегантність дизайну та робить прикрасу універсальною для щоденного носіння. Тонка основа гармонійно поєднується з сяйвом вставок, створюючи збалансований і витончений образ. Це прикраса, яка додає ніжного блиску будь-якому стилю та підкреслює вишуканий смак власниці.","en":"An elegant ring made of 585 red gold in an everyday “path” style, where a line of sparkling stones creates a continuous brilliance effect. The clean shape of the piece emphasizes the elegance of the design and makes it versatile for daily wear. The slim band harmoniously combines with the shimmer of the stones, creating a balanced and refined look. This piece adds a subtle sparkle to any style and highlights the refined taste of its wearer."}',0,1,'{"ua":"Дівчині, Нареченій, Дружині","en":"Girlfriend, Bride, Wife"}','{"size":18}');
