INSERT INTO products VALUES('84f24b87','chains','["https://img.ukrzoloto.ua/images/pr/520_520/c864101c11f40c2a7cd09408452f6159/1691049280/UZ10062834_000123094.webp", "https://img.ukrzoloto.ua/images/pr/520_520/c864101c11f40c2a7cd09408452f6159/1691049280/UZ10062834_000123094.webp", "https://img.ukrzoloto.ua/images/pr/520_520/191955bec9d2fbe6a66977613561ae18/1708465494/UZ10062834_000123094-r_1.webp", "https://img.ukrzoloto.ua/images/pr/520_520/52a9174a78afa57f6a5d8c5051322de4/1691049109/UZ10062834_000123094-t_1.webp", "https://img.ukrzoloto.ua/images/pr/520_520/972208e8a2fb4eeb5b060ec6011c99ba/1691653340/UZ10062834_000123094-f_1.webp"]','{"ua":"Ланцюжок з червоного золота 06307/5ц", "en":"Red gold chain 06307/5c"}',10000,1,1398.79999999999995,0,0,9.15000000000000035,'{"ua":"Алмазна грань","en":"Diamond Cut"}','{"ua":"Стандарт","en":"Standart"}','{"ua":"Золото", "en":"Gold"}','{"ua":"Червоний", "en":"Gold"}',585,'{"ua":"Унісекс","en":"Unisex"}','0','{"ua":"Без вставки","en":"Not"}','{"ua":"Пiд цей ланцюг можна носити кулони, підвіски .Його дизайн надає чоловікові мужності, а у панночки підкреслює жіночність за рахунок масивності плетіння. Плетіння бісмарк досить універсальне, адже добре поєднується із сукнею, сорочками, джинсами та спортивним одягом. І служить десятиліттями, оскільки червоне золото відрізняється особливою фортецею і майже неможливо деформувати.", "en":"Under this chain you can wear pendants, pendants. Its design gives a man masculinity, and in a young lady emphasizes femininity due to the massiveness of the weaving. Bismarck weaving is quite versatile, because it goes well with dresses, shirts, jeans and sportswear. And it serves for decades, because red gold is distinguished by its special strength and is almost impossible to deform."}',0,1,'{"ua":"Чоловікові, Сину, Братові, Татові, Дівчині", "en":"Husband, Son, Brother, Dad, Girlfriend"}','{"weaving_style":{"ua":"Бісмарк", "en":"Bismarck"}, "chain_width":{"ua":"3мм", "en":"3mm"}}');
