INSERT INTO products VALUES('e97a4113','chains','["https://img.ukrzoloto.ua/images/pr/520_520/5cb3c6615786679a0d24bd985dc82385/1696518922/UZ19055_000101569.webp", "https://img.ukrzoloto.ua/images/pr/520_520/1cf89461ad0e7782b1d4d6581c10fe06/1696518922/UZ19055_000101569-r_1.webp"]','{"ua":"Ланцюг з червоного золота 66938/6б","en":"Red gold chain 66938/6б"}',394,1,1094,0,0,2.60000000000000008,'{"ua":"Мінімалізм","en":"Minimalism"}','{"ua":"Стандарт","en":"Standart"}','{"ua":"Золото","en":"Gold"}','{"ua":"Червоний","en":"Red"}',585,'{"ua":"Унісекс","en":"Unisex"}','0','{"ua":"Нема","en":"None"}','{"ua":"Стильний ланцюг з червоного золота з панцирним плетінням. Легкий, блискучий та дуже зручний у носінні.","en":"Stylish red gold chain with anchor weaving. Lightweight, shiny and very comfortable to wear."}',0,1,'{"ua":"Дівчині, Жінці, Мамі, Сестрі","en":"Girlfriend, Wife, Mom, Sister"}','{"weaving_style":{"ua":"Панцирне","en":"Anchor"},"chain_width":{"ua":"2мм","en":"2mm"}}');
INSERT INTO products VALUES('1811a060','table_silver','["https://zolotiyvik.ua/media/catalog/product/cache/7d867076b0c31e5e4acf36489cc1e4f1/_/8/_8100529_-1.webp", "https://zolotiyvik.ua/media/catalog/product/cache/7d867076b0c31e5e4acf36489cc1e4f1/_/8/_8100529_-2.webp", "https://zolotiyvik.ua/media/catalog/product/cache/7d867076b0c31e5e4acf36489cc1e4f1/_/8/_8100529_-3.webp"]','{"ua":"Срібна ложка UG58100529", "en":"Silver spoon UG58100529"}',172.400000000000005,1,388,0,0,15.1699999999999999,'{"ua":"Релігія", "en":"Religion"}',NULL,'{"ua":"Срібло", "en":"Silver"}','{"ua":"Білий","en":"White"}',925,'{"ua":"Унісекс","en":"Unisex"}','0','{"ua":"Нема","en":"None"}','{"ua":"Елегантна срібна ложка стане не лише практичним виробом, а й особливим подарунком на важливу подію. Витончений рельєфний орнамент, деталізоване оздоблення ручки та благородний блиск срібла надають виробу аристократичного вигляду та підкреслюють його ексклюзивність. Дизайн поєднує класичні традиції ювелірного мистецтва з бездоганною якістю виконання.", "en":"An elegant silver spoon will be not only a practical product, but also a special memorable gift for an important event. The sophisticated relief ornament, detailed decoration of the handle and the noble shine of silver give the product an aristocratic look and emphasize its exclusivity. The design combines classic traditions of jewelry art with impeccable quality of workmanship."}',0,1,'{"ua":"Дівчині, Жінці, Мамі, Сестрі, Сину, Братові, Татові","en":"Girlfriend, Wife, Mom, Sister, Son, Brother, Dad"}',NULL);
INSERT INTO products VALUES('30990446','table_silver','["https://zolotiyvik.ua/media/catalog/product/cache/7d867076b0c31e5e4acf36489cc1e4f1/_/1/_1618_-1.webp", "https://zolotiyvik.ua/media/catalog/product/cache/7d867076b0c31e5e4acf36489cc1e4f1/_/1/_1618_-2.webp"]','{"ua":"Срібна ложка UG51618L", "en":"Silver spoon UG51618L"}',139.389999999999986,1,225.550000000000011,0,0,7.57000000000000028,'{"ua":"Релігія", "en":"Religion"}',NULL,'{"ua":"Срібло", "en":"Silver"}','{"ua":"Білий","en":"White"}',925,'{"ua":"Унісекс","en":"Unisex"}','0','{"ua":"Нема","en":"None"}','{"ua":"Вишукана срібна ложка з благородного срібла 925 проби поєднує в собі елегантний дизайн, високу якість виконання та довговічність. Її витончені лінії та акуратна форма роблять виріб не лише практичним столовим прибором, а й красивим елементом сервірування. Срібна ложка стане чудовим подарунком на хрестини, день народження, народження дитини або іншу важливу подію. Такий подарунок символізує добробут, турботу та сімейні традиції, а також може стати пам’ятною реліквією, що передаватиметься з покоління в покоління.","en":"An exquisite silver spoon made of 925 sterling silver combines elegant design, high quality workmanship and durability. Its graceful lines and neat shape make the product not only a practical cutlery, but also a beautiful element of serving. A silver spoon will be a wonderful gift for a christening, birthday, birth of a child or other important event. Such a gift symbolizes well-being, care and family traditions, and can also become a memorable heirloom that will be passed down from generation to generation."}',0,1,'{"ua":"Мамі, Сестрі, Сину, Братові","en":"Mom, Sister, Son, Brother"}',NULL);
INSERT INTO products VALUES('30990447','table_silver','["https://zolotiyvik.ua/media/catalog/product/cache/7d867076b0c31e5e4acf36489cc1e4f1/s/r/sribna-lozhka-8100082-foto-1.webp", "https://zolotiyvik.ua/media/catalog/product/cache/7d867076b0c31e5e4acf36489cc1e4f1/s/r/sribna-lozhka-8100082-foto-2.webp"]','{"ua":"Срібна ложка UG58100082", "en":"Silver spoon UG58100082"}',270.699999999999988,0,NULL,0,0,14,'{"ua":"Модерн", "en":"Modern"}',NULL,'{"ua":"Срібло", "en":"Silver"}','{"ua":"Білий","en":"White"}',925,'{"ua":"Унісекс","en":"Unisex"}','0','{"ua":"Нема","en":"None"}','{"ua":"Вишукана срібна ложка з ніжним квітковим орнаментом стане справжньою окрасою будь-якої колекції столового срібла. Витончений ажурний візерунок у вигляді квітів на ручці надає виробу особливої елегантності та підкреслює майстерність ювелірного виконання. Ложка виготовлена зі срібла 925 проби, що гарантує її довговічність, міцність і благородний блиск. Гармонійне поєднання класичної форми та декоративних елементів робить її чудовим вибором як для щоденного використання, так і для святкового сервірування столу.","en":"An exquisite silver spoon with a delicate floral ornament will be a real decoration of any collection of table silver. The elegant openwork pattern in the form of flowers on the handle gives the product a special elegance and emphasizes the skill of jewelry workmanship. The spoon is made of 925 silver, which guarantees its durability, strength and noble shine. The harmonious combination of classic shape and decorative elements makes it an excellent choice for both everyday use and festive table setting."}',0,1,'{"ua":"Дівчині, Жінці, Мамі, Сестрі, Сину, Братові, Татові","en":"Girlfriend, Wife, Mom, Sister, Son, Brother, Dad"}',NULL);
INSERT INTO products VALUES('30990448','table_silver','["https://zolotiyvik.ua/media/catalog/product/cache/7d867076b0c31e5e4acf36489cc1e4f1/_/8/_8100130_-1.webp", "https://zolotiyvik.ua/media/catalog/product/cache/7d867076b0c31e5e4acf36489cc1e4f1/_/8/_8100130_-2.webp"]','{"ua":"Срібна ложка UG58100130", "en":"Silver spoon UG58100130"}',234.120000000000004,1,402,0,0,21.9899999999999984,'{"ua":"Модерн", "en":"Modern"}',NULL,'{"ua":"Срібло", "en":"Silver"}','{"ua":"Білий","en":"White"}',925,'{"ua":"Жінкам","en":"Woman"}','0','{"ua":"Емаль","en":"Enamel"}','{"ua":"Ложка виконана з чистого срібла 925 проби, має світлий блискучий металевий відтінок завдяки родіюванню, що захищає поверхню від потемніння та додає виробу більш “дорогого” вигляду. На фото видно, що ручка ложки прикрашена декоративною емаллю, яка додає виробу кольорового акценту та робить дизайн більш ніжним і святковим.", "en":"The spoon is made of pure 925 sterling silver, has a light shiny metallic shade thanks to rhodium plating, which protects the surface from darkening and gives the product a more “expensive” look. The photo shows that the handle of the spoon is decorated with decorative enamel, which adds a colorful accent to the product and makes the design more delicate and festive."}',0,1,'{"ua":"Дівчині, Дружині, Мамі, Подрузі, Доньці", "en":"Girlfriend, Wife, Mother, Friend, Daughter"}',NULL);
INSERT INTO products VALUES('30990449','table_silver','["https://zolotiyvik.ua/media/catalog/product/cache/7d867076b0c31e5e4acf36489cc1e4f1/_/8/_8100283_-1.webp", "https://zolotiyvik.ua/media/catalog/product/cache/7d867076b0c31e5e4acf36489cc1e4f1/_/8/_8100283_-2.webp"]','{"ua":"Срібна ложка UG58100283", "en":"Silver spoon UG58100283"}',252.620000000000004,0,NULL,0,0,22.8399999999999998,'{"ua":"Завитки", "en":"Curls"}',NULL,'{"ua":"Срібло", "en":"Silver"}','{"ua":"Білий","en":"White"}',925,'{"ua":"Унісекс","en":"Unisex"}','0','{"ua":"Нема","en":"None"}','{"ua":"Це елегантна чайна ложка зі срібла 925 проби, виконана у класичному ювелірному стилі. Виріб має світлий блиск завдяки родіюванню, що захищає срібло від потемніння та надає йому більш “дзеркального”, преміального вигляду.","en":"This is an elegant teaspoon made of 925 silver, made in a classic jewelry style. The product has a light shine thanks to rhodium plating, which protects the silver from darkening and gives it a more “mirror-like”, premium look."}',0,1,'{"ua":"Дівчині, Жінці, Мамі, Сестрі, Сину, Братові, Татові","en":"Girlfriend, Wife, Mom, Sister, Son, Brother, Dad"}',NULL);
INSERT INTO products VALUES('30990450','table_silver','["https://zolotiyvik.ua/media/catalog/product/cache/7d867076b0c31e5e4acf36489cc1e4f1/_/1/_1620_-1.webp", "https://zolotiyvik.ua/media/catalog/product/cache/7d867076b0c31e5e4acf36489cc1e4f1/_/1/_1620_-2.webp"]','{"ua":"Срібна ложка UG51620L", "en":"Silver spoon UG51620Л"}',196.229999999999989,0,NULL,0,0,13.2100000000000008,'{"ua":"Завитки", "en":"Curls"}',NULL,'{"ua":"Срібло", "en":"Silver"}','{"ua":"Білий","en":"White"}',925,'{"ua":"Унісекс","en":"Unisex"}','0','{"ua":"Нема","en":"None"}','{"ua":"Це срібна чайна ложка 925 проби. Вона має простий класичний дизайн без декору — гладка, блискуча, з акуратною формою. Поверхня відполірована до дзеркального блиску, виглядає чисто і стримано. Це універсальна срібна ложка, яку можна подарувати або використовувати як класичний столовий виріб.","en":"This is a 925 sterling silver teaspoon. It has a simple classic design without decoration - smooth, shiny, with a neat shape. The surface is polished to a mirror shine, looks clean and restrained. This is a universal silver spoon that can be given as a gift or used as a classic tableware"}',0,1,'{"ua":"Мамі, Татові","en":"Mom, Dad"}',NULL);
